acts:[["09","rooms in three joglo houses"],["1920s","teak frames, restored by hand"],["5 min","walk to the Kraton"]],roomsEyebrow:"Rooms",roomsTitle:"Three houses, nine rooms",prev:"Previous room",next:"Next room",of:"of",swipe:"Swipe to browse",rooms:[{name:"Joglo Room",meta:"Garden courtyard · King bed · 2 guests",text:"Under a tiered joglo roof, with carved doors that open onto a frangipani courtyard.",alt:"Traditional Javanese joglo house with a tiered roof"},{name:"Pendhapa Suite",meta:"Private veranda · King bed · 3 guests",text:"Beside the open pendhapa, with a veranda of teak and a daybed for slow afternoons.",alt:"Carved teak pendopo pavilion of a traditional Javanese house"},{name:"Taman Residence",meta:"Two bedrooms · Plunge pool · 5 guests",text:"A walled house inspired by the water palace of Taman Sari, with its own pool and garden.",alt:"Carved gate of the Taman Sari water palace in Yogyakarta"}],askRoom:"Ask about this room",rasaEyebrow:"Rasa · Experiences",rasaTitle:"Days shaped by the city",rasa:[{t:"Batik with a master",d:"Draw with hot wax and a canting in our studio, then dye your cloth in sogan and indigo.",img:"batik",alt:"Batik maker drawing wax patterns on cloth in Yogyakarta"},{t:"Gudeg at dawn",d:"Young jackfruit slow-cooked in palm sugar and teak leaves, the breakfast of Yogyakarta.",img:"gudeg",alt:"A plate of gudeg with chicken, egg and rice"},{t:"The Sultan’s palace",d:"A morning walk through the Kraton with a guide who grew up inside its walls.",img:"kraton",alt:"Pavilion inside the Kraton, the Sultan’s palace of Yogyakarta"}],locEyebrow:"Location",locTitle:"In the old heart of Yogyakarta",locText:"We are inside the old city, near the Kraton and Taman Sari. Prambanan and Borobudur are an easy drive for sunrise, and we meet guests at Yogyakarta International Airport (YIA) or Tugu station.",locList:[["Kraton","5 min walk"],["Taman Sari","10 min walk"],["Prambanan","40 min drive"],["Borobudur","75 min drive"]],stayEyebrow:"Reserve",stayTi